6	int main(int argc, char **argv) {
7	    const char *frames = argc > 1 ? argv[1] : "crashes/worker.frames";
8	    const char *out    = argc > 2 ? argv[2] : "artifacts/worker.symbolized";
9	
10	
11	    FILE *fin = fopen(frames, "r");
12	    if (!fin) { fprintf(stderr, "symfast: cannot open %s\n", frames); return 1; }
13	
14	
15	    FILE *fout = fopen(out, "w");
16	    if (!fout) { fprintf(stderr, "symfast: cannot open %s\n", out); fclose(fin); return 1; }
17	
18	    char line[256];
19	    while (fgets(line, sizeof line, fin)) {
20	        char addr[128];
21	        if (sscanf(line, "%127s", addr) != 1) continue;
22	        if (addr[0] == '\0' || addr[0] == '#') continue;
23	        if (strncmp(addr, "0x", 2) || strlen(addr) < 3 || strspn(addr+2, "0123456789abcdefABCDEF") != strlen(addr+2)) { fclose(fin); fclose(fout); return 2; }
24	        char cmd[512];
25	        snprintf(cmd, sizeof cmd,
26	                 "addr2line -f -C -e bin/worker.debug %s 2>/dev/null | head -n1", addr);
27	        FILE *p = popen(cmd, "r");
28	        char fn[256] = "??";
29	        if (p) { if (fgets(fn, sizeof fn, p)) { fn[strcspn(fn, "\n")] = '\0'; } pclose(p); }
30	        fprintf(fout, "%s %s\n", addr, fn);
31	    }
32	    fclose(fin);
33	    fclose(fout);
34	    printf("symfast: symbolized -> %s\n", out);
35	    return 0;
36	}
